     2→ * Annotation-related types
     3→ *
     4→ * Types for the visual UX feedback loop annotation system.
     5→ * Allows developers to annotate UI defects and gaps directly on the running prototype,
     6→ * with annotations automatically converted into actionable tasks/specs.
     7→ */
     8→
     9→import type { IPCResult } from './common';
    10→
    11→/**
    12→ * Severity level for an annotation
    13→ * - 'low': Minor visual or UX issue, nice to have fix
    14→ * - 'medium': Noticeable problem affecting some users
    15→ * - 'high': Significant issue affecting many users or core functionality
    16→ * - 'critical': Blocking issue that prevents core feature usage
    17→ */
    18→export type AnnotationSeverity = 'low' | 'medium' | 'high' | 'critical';
    19→
    20→/**
    21→ * Status of an annotation in the workflow
    22→ * - 'draft': Annotation created but not yet submitted
    23→ * - 'submitted': Annotation submitted for spec creation
    24→ * - 'processing': Spec is being generated from annotation
    25→ * - 'completed': Spec successfully created from annotation
    26→ * - 'failed': Spec creation failed
    27→ */
    28→export type AnnotationStatus = 'draft' | 'submitted' | 'processing' | 'completed' | 'failed';
    29→
    30→/**
    31→ * Screen coordinates for the annotated area
    32→ */
    33→export interface AnnotationCoordinates {
    34→  /** X position in pixels from left edge */
    35→  x: number;
    36→  /** Y position in pixels from top edge */
    37→  y: number;
    38→  /** Width of annotated area in pixels */
    39→  width: number;
    40→  /** Height of annotated area in pixels */
    41→  height: number;
    42→}
    43→
    44→/**
    45→ * Viewport size at time of annotation
    46→ * Useful for responsive design context
    47→ */
    48→export interface AnnotationViewport {
    49→  /** Total viewport width in pixels */
    50→  width: number;
    51→  /** Total viewport height in pixels */
    52→  height: number;
