    65→  timestamp: string;
    66→  /** Base64 encoded PNG screenshot of the annotated area */
    67→  screenshot: string;
    68→  /** Coordinates defining the annotated screen region */
    69→  coordinates: AnnotationCoordinates;
    70→  /** User-provided description of the issue */
